// Your page first, then the peers. The order matters: everything downstream
// calls index 0 "you", and the digest is written from that point of view.
const cfg = $('Settings').first().json;

// The slug, lowercased, with any query string and trailing slash removed. Two
// spellings of the same page would otherwise be scraped twice and then
// benchmarked against each other.
function slugOf(raw) {
  const m = String(raw || '').trim().toLowerCase().match(/linkedin\.com\/company\/([^/?#]+)/);
  return m ? m[1] : null;
}

const you = slugOf(cfg.your_company_url);
if (!you) {
  throw new Error(
    'your_company_url in Settings is not a LinkedIn company page. Expected ' +
    'something like https://www.linkedin.com/company/your-company/ - copy it ' +
    'from the page itself, because a guessed slug returns zero rows rather ' +
    'than an error.'
  );
}

const peers = String(cfg.competitor_urls || '')
  .split(/[,\n]/)
  .map(slugOf)
  .filter((s) => s && s !== you);

const slugs = [you, ...new Set(peers)].slice(0, Math.max(2, Number(cfg.max_pages) || 6));

if (slugs.length < 2) {
  throw new Error(
    'A benchmark needs at least one competitor. Add LinkedIn company page URLs ' +
    'to competitor_urls in Settings, separated by commas.'
  );
}

// One request for every page. The dataset discovers per input, so the whole
// peer set is one crawl rather than one crawl each.
return [{
  json: {
    you,
    slugs,
    payload: slugs.map((s) => ({ url: 'https://www.linkedin.com/company/' + s + '/' })),
  },
}];

const p = $json || {};

if (p.error) {
  throw new Error(
    'Bright Data refused the crawl: ' + JSON.stringify(p.error).slice(0, 300)
  );
}

const status = String(p.status || '');

if (status === 'failed') {
  throw new Error(
    'The crawl failed at Bright Data. Snapshot ' + (p.snapshot_id || 'unknown') +
    '. Check the dataset in the Bright Data dashboard before rerunning.'
  );
}

// $runIndex is how many times this node has already run in this execution, so
// it is the poll count. Without a cap a snapshot that never finishes keeps the
// execution alive until the instance is restarted.
const polls = $runIndex + 1;
const MAX_POLLS = 24;

if (status !== 'ready' && polls >= MAX_POLLS) {
  throw new Error(
    'The crawl was still running after ' + polls + ' checks, about ' +
    (polls * 15) + ' seconds. Two companies at five posts each took 40 seconds ' +
    'when this was measured, so either max_pages and posts_per_page are high or ' +
    'Bright Data is backed up. Snapshot ' + (p.snapshot_id || 'unknown')
  );
}

// error_codes is where a page that does not resolve shows up, and it arrives on
// an otherwise successful crawl. Carried forward so the reader can name it.
return [{
  json: {
    snapshot_id: p.snapshot_id,
    status,
    ready: status === 'ready',
    records: p.records || 0,
    error_codes: p.error_codes || null,
    polls,
  },
}];

// One clean row per post, and the three fields nobody expects to be missing.
const cfg = $('Settings').first().json;
const plan = $('Build The Company List').first().json;
const minChars = Math.max(0, Number(cfg.min_post_chars) || 0);

// hashtags, images and videos are null rather than empty arrays when there are
// none - 7 of 10 rows had no hashtags, 5 no images, 6 no videos. `.length` on
// null throws, and the throw lands in a node that had already gone green.
const arr = (v) => (Array.isArray(v) ? v : []);

// A LinkedIn post is one of four things and they do not behave alike. The row
// does not carry a format field, so it comes from which media field is present.
function formatOf(row) {
  if (arr(row.videos).length || row.video_duration) return 'video';
  if (row.document_cover_image || row.document_page_count) return 'document';
  if (arr(row.images).length) return 'image';
  return 'text';
}

// The company a row belongs to is `discovery_input.url` - the page that was
// crawled - and NOT `user_id`. On a repost, `user_id` is the *original author*:
// six of Zendesk's ten rows came back under `chris-zendesk`,
// `adrianmcdermott`, `thomasverschoren` and `mathew-costianes-5aa990aa`, all
// employees whose posts the company page had shared. Grouping on user_id drops
// four of Zendesk's ten posts into companies that were never in the watchlist,
// and Zendesk's cadence is then understated by 40% on a run where every node is
// green. `account_type` is the corroborating tell: it is `Organization` on a
// page's own post and null on a reposted one.
function crawledSlug(row) {
  const url = ((row || {}).discovery_input || {}).url || '';
  const m = String(url).toLowerCase().match(/linkedin\.com\/company\/([^/?#]+)/);
  return m ? m[1] : String(row.user_id || '').toLowerCase();
}

const rows = $input.all().map((i) => i.json).filter((r) => r && (r.url || r.id));

const posts = rows.map((row) => {
  const followers = Number(row.user_followers) || 0;
  const likes = Number(row.num_likes) || 0;
  // There is no share count on this dataset, so the engagement surface is
  // reactions and comments and nothing else. Stated rather than implied,
  // because a rate that silently omits shares is not comparable to LinkedIn's
  // own number.
  const comments = Number(row.num_comments) || 0;
  const text = String(row.post_text || '');

  return {
    company: crawledSlug(row),
    author: String(row.user_id || '').toLowerCase(),
    url: row.url,
    posted_at: row.date_posted || null,
    // A repost carries somebody else's engagement. Counting it as the sharing
    // page's own performance flatters whoever reposts most.
    is_repost:
      String(row.post_type || '') === 'repost' ||
      String(row.user_id || '').toLowerCase() !== crawledSlug(row),
    followers,
    likes,
    comments,
    engagement: likes + comments,
    engagement_rate: followers ? Math.round(((likes + comments) / followers) * 1000000) / 10000 : null,
    format: formatOf(row),
    words: text ? text.trim().split(/\s+/).length : 0,
    hashtags: arr(row.hashtags).length,
    // HubSpot's newest post came back on pt.linkedin.com, in Portuguese. A page
    // that posts per region reads as a page with a language problem unless the
    // report can say which posts were localised.
    localised: /^https?:\/\/(?!www\.)[a-z]{2}\.linkedin\.com/.test(String(row.url || '')),
    excerpt: text.replace(/\s+/g, ' ').trim().slice(0, 220),
    usable: !!row.url && text.length >= minChars,
  };
});

// Every requested page, including the ones that returned nothing. A slug that
// does not resolve comes back as a successful crawl with no rows, and a page
// that quietly vanishes from a benchmark makes the remaining ones look better.
const seen = new Set(posts.map((p) => p.company));
const missing = plan.slugs.filter((s) => !seen.has(s));

return posts.concat(
  missing.map((company) => ({
    company,
    usable: false,
    missing: true,
    reason:
      'Bright Data returned no posts for this page. The crawl succeeded, so the ' +
      'usual cause is a slug that does not resolve - check the URL on LinkedIn ' +
      'itself rather than guessing it.',
  }))
).map((json) => ({ json }));

// Per company, from its own posts. Medians throughout: one viral post moves a
// mean by more than a year of steady work, and the mean then describes an
// accident rather than a habit.
const plan = $('Build The Company List').first().json;
const rows = $input.all().map((i) => i.json);

function median(values) {
  if (!values.length) return null;
  const s = values.slice().sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  const m = s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
  return Math.round(m * 10000) / 10000;
}

function daysSpanned(list) {
  const times = list.map((p) => Date.parse(p.posted_at)).filter((t) => !Number.isNaN(t));
  if (times.length < 2) return null;
  return (Math.max(...times) - Math.min(...times)) / 86400000;
}

return plan.slugs.map((company) => {
  const all = rows.filter((r) => r.company === company);
  const missing = all.find((r) => r.missing);
  const own = all.filter((r) => r.usable && !r.is_repost);
  const reposts = all.filter((r) => r.usable && r.is_repost);

  if (missing || !own.length) {
    return {
      json: {
        company,
        is_you: company === plan.you,
        usable: false,
        reason: missing ? missing.reason : 'No original posts came back for this page.',
      },
    };
  }

  const byFormat = {};
  ['text', 'image', 'video', 'document'].forEach((f) => {
    const set = own.filter((p) => p.format === f);
    if (set.length) {
      byFormat[f] = {
        posts: set.length,
        median_rate: median(set.map((p) => p.engagement_rate).filter((n) => n !== null)),
      };
    }
  });

  const span = daysSpanned(own);
  const best = Object.keys(byFormat).sort(
    (a, b) => (byFormat[b].median_rate || 0) - (byFormat[a].median_rate || 0)
  )[0] || null;

  return {
    json: {
      company,
      is_you: company === plan.you,
      usable: true,
      followers: own[0].followers,
      posts: own.length,
      reposts: reposts.length,
      // The share of output that is somebody else's work, which is its own
      // finding: a page that reposts half the time is not publishing weekly.
      repost_share_pct: Math.round((reposts.length / (own.length + reposts.length)) * 100),
      localised_posts: own.filter((p) => p.localised).length,
      median_rate: median(own.map((p) => p.engagement_rate).filter((n) => n !== null)),
      median_engagement: median(own.map((p) => p.engagement)),
      median_words: median(own.map((p) => p.words)),
      by_format: byFormat,
      best_format: best,
      // Cadence from the window the crawl actually covered, not from a
      // calendar assumption. Ten posts spanning six weeks and ten spanning six
      // days are opposite habits and the row count cannot tell them apart.
      window_days: span === null ? null : Math.round(span),
      posts_per_week: span && span >= 1 ? Math.round((own.length / span) * 7 * 10) / 10 : null,
      newest_post: own.map((p) => p.posted_at).sort().slice(-1)[0] || null,
    },
  };
});

// You against the middle of the field, format by format. Not against the best
// peer: one page having a viral fortnight is not a target, and chasing it is
// how a content plan turns into a chase.
const rows = $input.all().map((i) => i.json);
const you = rows.find((r) => r.is_you);
const peers = rows.filter((r) => !r.is_you && r.usable);
const broken = rows.filter((r) => !r.usable);

if (!you || !you.usable) {
  throw new Error(
    'No original posts came back for your own page, so there is nothing to ' +
    'benchmark. ' + ((you && you.reason) || '')
  );
}

function median(values) {
  const s = values.filter((n) => n !== null && n !== undefined).sort((a, b) => a - b);
  if (!s.length) return null;
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

const peerRate = median(peers.map((p) => p.median_rate));
const peerCadence = median(peers.map((p) => p.posts_per_week));
const peerWords = median(peers.map((p) => p.median_words));

// Format by format, because "post more video" is only advice if video is where
// the gap is - and on some pages video is where the peers are worse.
const gaps = [];
['text', 'image', 'video', 'document'].forEach((f) => {
  const yours = (you.by_format || {})[f];
  const theirs = median(
    peers.map((p) => ((p.by_format || {})[f] || {}).median_rate).filter((n) => n !== null && n !== undefined)
  );
  if (theirs === null) return;

  // A format you have not tried is a gap of a different kind, and saying "you
  // are 100% behind on document posts" about zero posts would be a lie.
  const untried = !yours;
  const ratio = untried || !theirs ? null : Math.round((yours.median_rate / theirs) * 100);

  gaps.push({
    format: f,
    your_posts: untried ? 0 : yours.posts,
    your_rate: untried ? null : yours.median_rate,
    peer_rate: Math.round(theirs * 10000) / 10000,
    index_vs_peers: ratio,
    untried,
    behind: untried ? true : ratio !== null && ratio < 90,
  });
});

const behind = gaps.filter((g) => g.behind);

return [{
  json: {
    you: you.company,
    your_followers: you.followers,
    your_rate: you.median_rate,
    peer_rate: peerRate === null ? null : Math.round(peerRate * 10000) / 10000,
    // The headline. 100 is level with the field; 60 means four in ten of the
    // reactions a peer post gets, per follower.
    index_vs_peers: peerRate ? Math.round((you.median_rate / peerRate) * 100) : null,
    your_posts: you.posts,
    // Null when the crawled posts all landed inside a single day, which is what
    // an active page looks like through a ten-post window. Reporting that as
    // "unknown" and stopping would be the wrong answer twice over, so the window
    // travels with it and the digest says which it is.
    your_window_days: you.window_days,
    your_cadence: you.posts_per_week,
    peer_cadence: peerCadence,
    your_median_words: you.median_words,
    peer_median_words: peerWords === null ? null : Math.round(peerWords),
    your_repost_share_pct: you.repost_share_pct,
    peers_compared: peers.length,
    pages_not_read: broken.map((b) => ({ company: b.company, reason: b.reason })),
    gaps,
    behind_on: behind.map((g) => g.format),
    // Named peer posts, so the recommendation can point at something real
    // rather than at an average.
    proof: $('Read The Posts').all()
      .map((i) => i.json)
      .filter((p) => p.usable && !p.is_repost && p.company !== you.company && behind.some((g) => g.format === p.format))
      .sort((a, b) => (b.engagement_rate || 0) - (a.engagement_rate || 0))
      .slice(0, 6)
      .map((p) => ({
        company: p.company,
        format: p.format,
        rate: p.engagement_rate,
        words: p.words,
        url: p.url,
        excerpt: p.excerpt,
      })),
  },
}];

// One sheet row per company per run, so the sheet becomes the trend the
// benchmark cannot see in a single week.
const b = $('Compare With Your Page').first().json;
const today = new Date().toISOString().slice(0, 10);

const rows = $('Score Each Company').all()
  .map((i) => i.json)
  .filter((c) => c.usable)
  .map((c) => ({
    run_date: today,
    company: c.company,
    posts: c.posts,
    followers: c.followers,
    median_engagement_rate: c.median_rate,
    best_format: c.best_format || '',
    posts_per_week: c.posts_per_week === null ? '' : c.posts_per_week,
  }));

// A single-item input by construction: the chain above answers once for the
// whole benchmark, because Compare With Your Page emits exactly one row.
const reading = String(($input.first().json || {}).text || '').trim();

const line = (g) =>
  '- *' + g.format + '*: ' +
  (g.untried
    ? 'you have not posted one; peers median ' + g.peer_rate + '%'
    : 'you ' + g.your_rate + '% against a peer median of ' + g.peer_rate + '% (index ' + g.index_vs_peers + ')');

const msg = [];
msg.push('*LinkedIn benchmark* - ' + today);
msg.push(
  '*' + b.you + '* is at index *' + (b.index_vs_peers === null ? 'n/a' : b.index_vs_peers) +
  '* against ' + b.peers_compared + ' peers ' +
  '(' + b.your_rate + '% engagement per follower, peer median ' + b.peer_rate + '%).'
);
msg.push('');
msg.push(reading || '_no reading was returned this week_');
msg.push('');
msg.push('*By format*');
b.gaps.forEach((g) => msg.push(line(g)));
msg.push('');
const cadence =
  b.your_cadence !== null
    ? b.your_cadence + '/week'
    : b.your_window_days !== null
      ? b.your_posts + ' posts inside ' + (b.your_window_days || 1) + ' day(s)'
      : 'not enough dated posts to say';
msg.push(
  '*Cadence*: you ' + cadence +
  ', peers ' + (b.peer_cadence === null ? 'unknown' : b.peer_cadence + '/week') +
  '.  *Length*: you ' + b.your_median_words + ' words, peers ' + b.peer_median_words + '.'
);
if (b.your_repost_share_pct >= 30) {
  msg.push('_' + b.your_repost_share_pct + '% of your output is reposts, which is somebody else\'s engagement._');
}
// Never silently. A page that dropped out makes every remaining one look better.
if (b.pages_not_read.length) {
  msg.push('');
  msg.push('*Not read*');
  b.pages_not_read.forEach((p) => msg.push('- ' + p.company + ': ' + p.reason));
}

// A single item holding the rows array, and a Split Out below it. Handing this
// straight to Sheets writes one row whose columns are `message` and `rows` - a
// JSON blob where the description promised one row per company.
return [{ json: { message: msg.join('\n'), rows, row_count: rows.length } }];
